Could you please check the implementation method as follows?
void MctpDiscovery::getAddedMctpInfos(sdbusplus::message_t& msg,
                                      MctpInfos& mctpInfos)
{
    using ObjectPath = sdbusplus::message::object_path;
    ObjectPath objPath;
    using pldm::utils::PropertyMap;
    std::map<std::string, PropertyMap> interfaces;
    std::string uuid = emptyUUID;

    try
    {
        msg.read(objPath, interfaces);
    }
    catch (const std::exception& e)
    {
        lg2::error("Failed to read InterfacesAdded message: {ERROR}", "ERROR",
                   e.what());
        return;
    }

    const std::string mctpInterface = MCTPEndpoint::interface;
    const std::string assocInterface =
        "xyz.openbmc_project.Association.Definitions";

    bool hasEndpointInSignal = interfaces.contains(mctpInterface);
    bool hasAssocInSignal = interfaces.contains(assocInterface);

    // Only proceed if the signal contains either Endpoint or Association
    if (!hasEndpointInSignal && !hasAssocInSignal)
    {
        return;
    }

    pldm::utils::DBusHandler dbusHandler;

    // Verification of Association
    // If Association is not in the current signal, check if it exists on D-Bus
    if (!hasAssocInSignal)
    {
        try
        {
            dbusHandler.getService(objPath.str.c_str(), assocInterface.c_str());
        }
        catch (const std::exception& e)
        {
            lg2::info(
                "MCTP Path '{PATH}' is missing Association. Waiting for MCTPReactor signal.",
                "PATH", objPath.str);
            return;
        }
    }

    // Retrieval of MCTP Endpoint Properties
    PropertyMap properties;
    if (hasEndpointInSignal)
    {
        properties = interfaces.at(mctpInterface);
    }
    else
    {
        try
        {
            auto service = dbusHandler.getService(objPath.str.c_str(),
                                                 mctpInterface.c_str());
            properties = dbusHandler.getDbusPropertiesVariant(
                service.c_str(), objPath.str.c_str(), mctpInterface.c_str());
        }
        catch (const std::exception& e)
        {
            lg2::info(
                "MCTP Path '{PATH}' is missing Endpoint data. Waiting for MCTPD signal.",
                "PATH", objPath.str);
            return;
        }
    }

